    (IPStandardizedYield _SY, IPPrincipalToken _PT,) = IPMarket(market).readTokens();
    IERC20(address(_SY)).safeTransfer(address(market), SYamount);
    IERC20(address(_PT)).safeTransfer(address(market), PTamount);
    market.mint(address(this), SYamount, PTamount);
    market.skim();
    emit DepositIntoMarket(address(market), SYamount, PTamount);
}

function skim() external nonReentrant {
    MarketState memory market = readState(msg.sender);
    uint256 excessPt = _selfBalance(PT) - market.totalPt.Uint();
    uint256 excessSy = _selfBalance(SY) - market.totalSy.Uint();
    if (excessPt != 0) IERC20(PT).safeTransfer(market.treasury, excessPt);
    if (excessSy != 0) IERC20(SY).safeTransfer(market.treasury, excessSy);
}

